    explanation: "反証可能性は、科学と非科学を分ける基準としてポパーが重視した概念です。ある理論がどんな結果でも説明できてしまうなら、一見強そうに見えますが、実は危険です。なぜなら、間違いだと示される可能性がないからです。ポパーにとって科学的理論は、経験によって否定されるリスクを引き受けなければなりません。たとえば「すべての白鳥は白い」という命題は、黒い白鳥が一羽見つかれば反証されます。だから経験的にテスト可能です。一方で、どんな出来事もあとから都合よく解釈して説明できる理論は、予言や検証の力が弱くなります。ポパーは、科学を確実な真理の集まりではなく、大胆な仮説を立て、それを厳しい批判とテストにさらす営みとして見ました。ニュートン力学も、長く成功した理論でしたが、水星の軌道や光の振る舞いなどを通じて限界が明らかになり、相対性理論へと進みました。ただし、現実の科学は一つの反例だけですぐ理論を捨てるほど単純ではありません。測定誤差や補助仮説もあります。それでも反証可能性は、科学的な態度とは何かを考える基本です。",
