    explanation: "「隣人を愛せよ」は、キリスト教倫理を代表する言葉です。もともとはレビ記にも見える教えですが、新約聖書ではイエスが最も重要な戒めの一つとして語ります。ここでの隣人は、単に家の近くに住む人や仲のよい人だけではありません。ルカ福音書の「善きサマリア人」のたとえが象徴的です。強盗に襲われた人を、同じ共同体の宗教者たちは通り過ぎますが、当時ユダヤ人と対立関係にあったサマリア人が助けます。イエスは、誰が隣人かを分類するのではなく、苦しむ人に隣人として振る舞ったのは誰かを問いました。この転換が重要です。愛は感情として好きになることだけでなく、相手を生かす具体的な行為として示されます。敵を愛せよという教えともつながり、血縁、民族、身分、宗教的境界を越える倫理として理解されました。一方で、この言葉はしばしば道徳的スローガンとして軽く使われます。実際には、自分の安全や利益と衝突する他者をどう扱うかという厳しい問いです。福祉、難民、差別、貧困、赦しの問題を考えるときにも、隣人とは誰かという問いは残り続けます。",
