    explanation: "ハロー効果は、一つの目立つ印象が他の評価まで照らしてしまう現象です。halo は後光を意味します。たとえば見た目が清潔で話し方が自信に満ちている人を見ると、実際には分からない専門能力や誠実さまで高く評価してしまうことがあります。逆に一つの失敗や悪い印象が、その人全体の評価を下げることもあります。ソーンダイクは軍隊での評価研究から、上官が部下の体格、知性、リーダーシップ、性格などを相互に独立して評価できず、全体印象に引きずられることを示しました。現代でも、面接、学校の成績評価、商品レビュー、政治家のイメージ、ブランド戦略に関わります。有名企業の製品だから品質もよいはずだ、人気者の発言だから正しいはずだ、という判断もハロー効果に近いものがあります。これは人間が限られた情報から素早く判断するための近道でもありますが、誤った評価を生みやすい。対策としては、評価項目を分ける、具体的な証拠を見る、第一印象と実績を区別することが重要です。ハロー効果を知ると、自分の判断がどれだけ雰囲気に左右されるかに気づけます。",
