    explanation: "ウェーバーの支配の三類型は、なぜ人々が命令に従うのかを考えるための枠組みです。支配は単なる暴力だけでは長続きしません。人々がその支配を正当だと信じる根拠が必要です。伝統的支配は、昔からそうだから、家柄や慣習があるから従うという形です。王朝や家父長制が例になります。カリスマ的支配は、指導者の非日常的な魅力、英雄性、預言者的力への信頼にもとづきます。革命家、宗教指導者、戦時の英雄などが典型です。合法的支配は、法律や規則、職務権限に従う形で、近代官僚制や民主国家に見られます。現代の役所で窓口担当者に従うのは、その人の血筋や魅力ではなく、法的な職務権限があるからです。この類型は現実をきれいに三分するものではなく、実際の政治では混ざり合います。選挙で選ばれた指導者がカリスマを持つこともありますし、伝統的権威が法制度に組み込まれることもあります。支配の三類型を知ると、権力がどんな理由で受け入れられ、どこで危うくなるのかを分析しやすくなります。",
