    explanation: "ダニング＝クルーガー効果は、能力の低い人ほど自分の能力不足を認識しにくいという心理学の概念です。何かをうまく行うには、その分野の知識や技能が必要です。しかし、自分がどれだけできているかを評価するにも、同じように知識や技能が必要になります。つまり、未熟な人は課題をこなせないだけでなく、自分がどこで間違っているのかも見えにくい。これが過大な自己評価につながります。たとえば少しだけ専門用語を覚えた段階で、複雑な問題を簡単だと思い込むことがあります。一方、学びが進むと、知らないことの広さが見え、自己評価が一時的に下がることもあります。ただし、この効果は「愚かな人を笑うため」の言葉ではありません。誰でも未知の分野では同じ罠に落ちます。また、近年は統計的な説明や効果の解釈についても議論があります。重要なのは、自信と能力は必ずしも一致しないこと、そしてフィードバック、訓練、他者の評価が必要だという点です。自分は分かっているという感覚ほど、検証が必要です。この概念は学習態度を謙虚にするために使うと有益です。",
