    explanation: "アンカリング効果は、最初に提示された数値や情報が錨のように働き、その後の判断を引きずる現象です。たとえば商品の定価が一万円と示された後に六千円と表示されると、安く感じやすくなります。最初に高い金額を提示された交渉では、その金額を基準に値引き幅を考えてしまうことがあります。カーネマンとトヴェルスキーの研究では、無関係な数字でさえ推定に影響することが示されました。国連加盟国の中でアフリカ諸国が占める割合を推定する前に、ルーレットで出た数字を見るだけでも、その数字が推定値を引っ張る場合があります。人間は未知の量を判断するとき、何か手がかりを出発点にして調整します。しかし調整は十分ではなく、最初の値に近いところに残りがちです。これは買い物、給与交渉、不動産価格、裁判の量刑、予算見積もりなど多くの場面で働きます。アンカリングを避けるには、先に独自の基準を持つ、複数の比較対象を見る、最初の数字がどこから来たのかを疑うことが有効です。情報の順番が判断を形づくることを教える概念です。",
