    explanation: "プロスペクト理論は、人間の意思決定が古典的な合理性モデルとずれることを示した行動経済学の代表理論です。カーネマンとトヴェルスキーは、人は最終的な富の量そのものより、基準点からの利益や損失として結果を感じると考えました。特に重要なのが損失回避です。同じ金額でも、得をした喜びより損をした痛みの方が強く感じられます。そのため、人は利益が出ている場面では確実な小さな得を選びやすく、損失が出ている場面では一発逆転を狙ってリスクを取りやすくなります。株で含み益は早く確定したがり、含み損はなかなか損切りできない心理にも関係します。また、確率の感じ方も歪みます。非常に低い確率を過大評価して宝くじを買ったり、まれな事故を過度に恐れたりすることがあります。プロスペクト理論は、保険、投資、消費、政策広報、医療判断などに広く応用されました。これは人間が非合理でだめだという話ではなく、現実の人間がどのような心理的ルールで選んでいるかを捉える理論です。選択の提示方法、つまりフレーミングが判断を変えることも重要です。",
