    explanation: "脱構築は、デリダの現代思想を代表する言葉です。よく「壊すこと」と誤解されますが、単に破壊するという意味ではありません。あるテキストや制度、概念が、どんな対立や前提によって成り立っているのかを丁寧に読み解き、その内部にある揺らぎや矛盾を明らかにする実践です。西洋哲学では、話し言葉が書き言葉より本物に近い、精神が身体より上、理性が感性より上、男性が女性より中心、といった階層的な二項対立がしばしば前提にされてきました。デリダは、下位に置かれたものが実は上位のものを支えていること、意味が完全に固定されず差異の連鎖の中で成立することを示そうとしました。脱構築は、何でも相対化して意味がないと言うための道具ではありません。むしろ、当たり前に見える言葉や制度が、どんな排除や抑圧を含んでいるのかを読む方法です。文学批評、法学、ジェンダー論、建築、文化研究にも影響しました。ただし、難解な言葉として濫用されることも多く、単に既存のものを壊す改革という意味で使うと、本来の緻密な読解から離れてしまいます。",
