    explanation: "キャッチ=22は、ジョセフ・ヘラーの小説『キャッチ=22』に由来する言葉です。第二次世界大戦中の爆撃隊を舞台に、軍の官僚制、不条理、狂気が風刺されます。有名なのは、危険な任務を避けるためには精神異常を申請できるが、危険だから任務を避けたいと判断できるなら正気であり、したがって任務を避けられない、という矛盾した規則です。逃げるための条件を満たそうとすると、その条件を満たしていないことになる。これがキャッチ=22です。現代では、仕事を得るには経験が必要だが、経験を得るには仕事が必要だ、身分証を作るには住所が必要だが、住所を得るには身分証が必要だ、というような制度的な袋小路を指します。この語の力は、単なる困難ではなく、規則そのものが矛盾していて、合理的に行動するほど抜け出せない状況を表す点にあります。ヘラーの作品では、戦争の非人間性が、英雄的な悲劇ではなく、笑えるほど理不尽な官僚制として描かれます。キャッチ=22を知ると、不条理は抽象的な哲学だけでなく、制度や書類や規則の中にも現れることが分かります。",
