    explanation: "相補性原理は、ボーアが量子力学を解釈するために示した考えです。電子や光は、ある実験では粒子のように振る舞い、別の実験では波のように振る舞います。日常感覚では、粒であることと波であることは両立しないように見えます。しかし量子の世界では、どちらか一方だけで完全に説明することはできません。実験の設定によって現れる側面が変わり、互いに排他的に見える記述が、全体としては対象を理解するために必要になります。二重スリット実験を考えると分かりやすいでしょう。どちらのスリットを通ったかを調べないと干渉縞が現れ、波のような性質が見えます。通過経路を測ろうとすると、その干渉の様子は変わり、粒子のような側面が前に出ます。相補性原理は、観測者が気分で現実を作るという意味ではありません。どのような測定条件で何が言えるのかを厳密に考える必要があるということです。ボーアとアインシュタインの論争でも、この量子論の解釈は大きなテーマでした。相補性は、科学が一つの直感的な絵だけで自然を捉えられない場合があることを示しています。",
