    explanation: "カフカ的とは、フランツ・カフカの小説に見られるような、不条理で圧迫的、しかも妙に日常的な状況を表す言葉です。『審判』では、主人公ヨーゼフ・Kが理由も知らされないまま逮捕され、正体のはっきりしない裁判制度に巻き込まれます。『城』では、主人公が城の権力に近づこうとしても、手続きと伝言と役人の壁に阻まれます。カフカ的な世界では、巨大な権力が露骨に暴力を振るうというより、書類、窓口、規則、沈黙、説明不足が人を追い詰めます。何が罪なのか、誰が決定しているのか、どこへ行けば話が通じるのかが分からない。現代でも、複雑な行政手続き、企業のクレーム対応、アルゴリズムによるアカウント停止、理由の分からない審査落ちなどで、カフカ的という表現が使われます。ただし、単に面倒な手続きを何でもカフカ的と呼ぶと薄くなります。カフカの怖さは、不条理が悪夢のようでありながら、どこか現実の制度に似ている点です。個人が意味を求めても、制度は説明しない。そのずれが、近代社会の孤独と不安を鋭く描きます。",
