    explanation: "乗数効果は、ある支出の増加が、経済全体ではその何倍もの所得増加につながる可能性を示すケインズ経済学の概念です。たとえば政府が公共事業に100億円を支出すると、建設会社や労働者に所得が生まれます。その労働者が給料の一部を消費すれば、小売店や飲食店の売上になります。そこで働く人の所得も増え、さらに消費が続きます。このように支出が次々に誰かの所得となり、経済全体に波及します。不況時に民間が投資や消費を控えているとき、政府支出で需要を補うという財政政策の理屈はここにあります。ただし、乗数効果の大きさは状況によって変わります。人々が所得を貯蓄に回す割合が高い、輸入品に支出が流れる、供給能力が足りない、政府債務への不安で民間が支出を控える、といった場合は効果が小さくなります。逆に失業や遊休設備が多いときは効果が出やすいとされます。乗数効果は、財政支出をすれば必ず何倍にも増えるという魔法ではなく、需要不足の経済で支出の連鎖をどう見るかという考えです。",
