    explanation: "CAP定理は、分散システムを理解するための有名な考えです。Cは一貫性、Aは可用性、Pは分断耐性を表します。一貫性は、どのノードに問い合わせても同じ最新データが見えることです。可用性は、リクエストに必ず応答できることです。分断耐性は、ネットワークが切れて一部のノード同士が通信できなくてもシステムが動き続けることです。分散システムではネットワーク分断を完全には避けられません。そのとき、最新データの一致を優先して応答を止めるのか、多少古いデータでも応答を返すのかという選択が生じます。銀行残高のように一貫性が重要な場面と、SNSのタイムラインのように一時的な遅れを許容できる場面では設計が変わります。ただし、CAP定理は三つから二つを単純に選ぶチェックリストではありません。遅延、復旧、整合性の種類、業務要件によって設計はもっと細かくなります。クラウド時代の信頼性を考える基本語です。",
