    explanation: "メタ認知は、自分が何を知っていて、何を知らず、どのように考えているかを一段上から見る働きです。単に頭がよいという意味ではありません。たとえば試験勉強で、読んだだけで分かった気になっているのか、実際に説明できるのかを点検する。問題を解く途中で、今の方針がうまくいっていないと気づき、別の方法に切り替える。会話の中で、自分が感情的に反応していることに気づいて一度止まる。こうした働きがメタ認知です。心理学ではフラベルらの研究を通じて注目され、学習科学や教育で重視されます。メタ認知が高い人は、分からないことを分からないと言いやすく、質問や復習の計画を立てやすい。逆に低いと、理解できていないのに過信したり、簡単な作業に時間を使いすぎたりします。このアプリの未読、既読、定着のような自己評価も、メタ認知の小さな訓練になります。現代では、情報過多の中で自分の判断の癖を点検する力としても重要です。",
