    explanation: "ゲートキーピングは、どの情報が人々に届き、どの情報が届かないかを決める選別の過程を指します。新聞やテレビでは、記者、編集者、デスク、放送枠、紙面の大きさ、取材先との関係などが、ニュースの入口を管理していました。事件が毎日大量に起きても、紙面や番組時間は限られるため、何を一面にするか、何を短い記事にするか、何を取り上げないかが判断されます。この選別は単なる陰謀ではなく、ニュース価値、速報性、公共性、視聴率、組織文化、政治的圧力などが絡む現実的な過程です。SNS時代には、誰でも発信できるためゲートキーパーは消えたように見えます。しかし実際には、プラットフォームのアルゴリズム、検索順位、広告審査、アカウント凍結、インフルエンサーの拡散力が新しいゲートになります。ゲートキーピングを知ると、報道された情報だけで社会を見ていないか、逆に表示されない情報が何かを考えられます。メディア・リテラシーの基礎になる概念です。",
