    explanation: "培養理論は、テレビなどのメディアに長期間接することで、人々の現実認識が少しずつ形作られるという考えです。ガーブナーは、テレビの暴力描写を研究し、テレビをよく見る人ほど現実社会を危険だと感じやすい傾向に注目しました。これは、ある番組を一回見たからすぐ行動が変わるという単純な影響論ではありません。むしろ、似たような物語、役割、犯罪、家族像、職業像、成功像を繰り返し見ることで、世界とはこういうものだという感覚が培養されるという発想です。たとえばニュースやドラマで犯罪が多く描かれれば、実際の統計以上に治安が悪いと感じるかもしれません。広告やバラエティが特定の美しさや生活水準を当然のように示せば、欲望や劣等感の基準にもなります。現代ではテレビだけでなく、動画配信、SNS、ショート動画、ゲーム配信にも広げて考えられます。ただし、受け手は完全に受動的ではなく、経験やコミュニティによって解釈も変わります。培養理論は、日々のメディア環境が空気のように世界観を作ることを意識させる語です。",
