    explanation: "有効需要は、単なる欲しいという気持ちではなく、実際に支払い能力を伴って市場に現れる需要を指します。ケインズは、不況や失業を説明するうえで有効需要を重視しました。古典派的な見方では、賃金や価格が調整されれば市場は均衡し、失業は解消されると考えられがちでした。しかし現実には、人々が将来不安から消費を控え、企業も売れないと見て投資を控えると、需要が不足し、生産が減り、雇用が減ります。雇用が減れば所得が減り、さらに消費が落ちるという悪循環が起こります。このとき、働きたい人がいて、生産能力もあるのに、十分な有効需要がないために経済が停滞します。ケインズは、政府の財政政策や公共投資が需要を補う役割を持ちうると考えました。有効需要の概念は、経済が供給能力だけで決まるのではなく、人々の所得、期待、不安、投資意欲によって動くことを示します。不況時に節約が美徳でも全員が節約すると景気が悪化するという合成の誤謬とも関係します。",
    note: "需要という言葉でも、欲望一般ではなく購買力を伴う需要を指す。ケインズ政策理解の要になる。",
    tags: ["ケインズ", "不況", "財政政策"],
