    explanation: "スティグマは、ある属性が社会的に否定的な印として扱われ、その人の評価や扱いを大きく左右することを指します。語源的には身体に刻まれた印に関係しますが、社会学ではゴフマンの研究で有名です。病気、障害、貧困、前科、依存症、職業、出自、性的指向、精神疾患など、さまざまな属性がスティグマ化されることがあります。問題は、その属性そのものだけではありません。社会がそれを恥ずべきもの、危険なもの、劣ったものとして扱うことで、本人は隠す、避ける、自己評価を下げる、支援を求めにくくなるといった影響を受けます。たとえば精神疾患への偏見が強い社会では、早く相談すればよい状態でも、周囲に知られることを恐れて受診が遅れることがあります。感染症でも、病気そのものの苦しみに加えて差別が人を追い詰めます。スティグマを知ると、差別は悪意ある個人だけでなく、言葉、制度、メディア表象、沈黙によって維持されることが分かります。",
