    explanation: "象徴資本は、名声、信用、権威、学歴、格式、品位、称号のように、社会的に価値あるものとして認められる資本です。ブルデューは、資本をお金だけに限らず、文化資本、社会関係資本、象徴資本として広く捉えました。たとえば同じ発言でも、無名の人が言うのと、有名大学の教授や権威ある賞の受賞者が言うのでは受け取られ方が違います。老舗ブランド、名門校、伝統ある家柄、専門資格、フォロワー数も、象徴資本として働くことがあります。象徴資本の特徴は、それが社会的に承認されているときだけ力を持つことです。人々がその肩書きや名声に価値を認めるからこそ、影響力が生まれます。また、経済資本が象徴資本に変わることもあります。寄付によって名誉を得る、高価な教育を通じて学歴を得る、文化的な洗練を身につけるといった形です。象徴資本を知ると、社会の不平等が単に所得の差だけでなく、信頼される声、尊敬される態度、正統とされる文化をめぐっても作られることが分かります。",
