    explanation: "言語ゲームは、後期ウィトゲンシュタインの中心概念です。彼は、言葉の意味を、言葉が何かを指し示す対応関係だけで理解するのは不十分だと考えました。言葉は、命令する、質問する、祈る、冗談を言う、約束する、計算する、謝る、名前をつけるなど、さまざまな活動の中で使われます。チェスの駒が盤上のルールの中で意味を持つように、言葉も生活の形式の中で役割を持ちます。たとえば「痛い」という言葉は、内側の感覚に貼られた単なる名前ではなく、助けを求める、訴える、説明する、同情されるといった社会的な使い方と結びついています。言語ゲームを知ると、哲学の混乱の多くは、言葉を本来の使い方から切り離し、別のゲームのルールで扱うことから生まれると分かります。これは、真理が何でも相対的だという意味ではありません。意味を理解するには、実際の使い方、文脈、ルール、共同体の実践を見る必要があるという考えです。",
