    explanation: "チューリングマシンは、計算とは何かを数学的に考えるためにアラン・チューリングが示した抽象的な機械です。無限に長いテープ、記号を読み書きするヘッド、状態と規則からなる単純なモデルですが、計算手順の本質を捉えます。人間が紙と鉛筆で規則的に計算する過程を、機械的な操作として形式化したものです。重要なのは、実際の装置として作るための設計図ではなく、どんな問題が計算可能なのかを問う理論モデルである点です。チューリングは、このモデルを使って、すべての問題が機械的に解けるわけではないことを示しました。現代のコンピュータはチューリングマシンそのものではありませんが、プログラムを読み込み、手順に従って計算するという発想は深く関係します。万能チューリングマシンの考えは、一つの機械がさまざまなプログラムを実行できるという現代的なコンピュータの原型にもなりました。チューリングマシンを知ると、コンピュータは単なる便利な機械ではなく、計算可能性という深い数学的問いから生まれたことが分かります。",
