    explanation: "エポケーは、フッサール現象学の中心的な方法を表す言葉です。私たちはふだん、机、家、他人、社会、歴史が当然そこにあるものとして生活しています。フッサールは、この日常的な信念を否定するのではなく、いったん判断停止して括弧に入れ、ものが意識にどのように現れているのかを丁寧に見る必要があると考えました。たとえば目の前のコップを見るとき、私たちは色や形だけでなく、裏側もある、手に取れる、水を入れられる物として経験しています。エポケーは、こうした経験の構造を取り出すための姿勢です。これは懐疑論のように世界の存在を疑い続けることではありません。むしろ、世界について性急に結論する前に、経験そのものに戻る訓練です。科学も常識も世界を前提にして進みますが、その前提がどのように成り立っているかを問うのが現象学です。エポケーを知ると、哲学が抽象的な理屈だけでなく、見える、感じる、意味づけるという身近な経験から始まることが分かります。",
