    explanation: "演繹法は、前提が正しく、推論の形も正しければ、結論も必ず正しくなるタイプの推論です。典型例は「すべての人間は死ぬ。ソクラテスは人間である。したがってソクラテスは死ぬ」という三段論法です。ここでは、結論は前提の中に含まれている内容を論理的に取り出したものです。数学の証明は演繹の代表です。公理や定義から出発し、規則に従って定理を導きます。演繹法の強みは、結論の確実性です。一方で、前提そのものが間違っていれば、形式が正しくても現実に合わない結論が出ます。たとえば「すべての鳥は飛ぶ」という前提からペンギンについて結論を出せば、前提が粗いため誤ります。また、演繹だけでは新しい経験的事実を発見することは難しい。科学では、理論から予測を演繹し、それを観察や実験で確かめるという形で使われます。演繹法を知ると、議論の正しさを考えるとき、前提の真偽と推論形式の妥当性を分けて見る習慣が身につきます。これは数学だけでなく、法律、政策、日常の議論にも役立ちます。",
    note: "一般から個別へという説明は便利だが、核心は前提から結論が必然的に導かれる推論形式にある。",
