    explanation: "帰納法は、個別の観察から一般的な法則や傾向を導く推論です。何度も太陽が東から昇るのを見て、明日も東から昇るだろうと考える。多くの金属を熱すると膨張するのを観察して、金属は熱で膨張しやすいと考える。こうした推論は科学や日常生活に不可欠です。経験から学ぶとは、多くの場合、帰納によってパターンを見つけることです。しかし帰納法には根本的な問題があります。これまでそうだったからといって、未来も必ずそうとは限りません。ヒュームは、自然が将来も過去と同じように振る舞うという前提そのものを、経験だけでは証明できないと指摘しました。有名な例では、白い白鳥を何羽見ても、すべての白鳥が白いとは確定できず、黒い白鳥が一羽見つかれば崩れます。それでも帰納を捨てることはできません。科学では、観察数を増やし、条件を管理し、統計を用い、反証可能な仮説として扱うことで、帰納の弱点を補います。帰納法を知ると、データから結論を出すとき、どこまで一般化してよいのか、例外や偏りはないのかを慎重に考えられます。",
