    explanation: "損失回避は、人が利益の喜びよりも損失の痛みを強く感じる傾向です。たとえば一万円を得る喜びより、一万円を失う痛みの方が大きく感じられることがあります。この非対称性は、カーネマンとトヴェルスキーのプロスペクト理論で重要な役割を持ちました。人は絶対的な資産額より、今の状態から増えたか減ったかを基準に判断しやすいのです。そのため、値下げよりも損を避ける表示の方が強く効いたり、含み損の株を売れずに抱え続けたり、現状維持に過度にこだわったりします。損失回避は消費者行動、投資、保険、政策広報に広く関係します。ただし、損を嫌うこと自体は不合理ではありません。生存や生活の安定を考えれば、損失への敏感さは意味があります。問題は、その感覚が実際の確率や長期的利益を見えにくくする場合です。損失回避を知ると、自分の判断が恐怖に引っ張られていないか確認しやすくなります。",
