    explanation: "pハッキングは、統計的に有意な結果が出るまで、分析対象、期間、変数、除外基準、検定方法をあれこれ試し、その結果を最初から予定していた発見のように示してしまう問題です。科学研究では、p値が一定以下なら偶然ではなさそうだと判断する慣行があります。しかし多数の組み合わせを試せば、偶然に有意な結果が出ることがあります。たとえば、食品、性格、健康効果の関係を大量に調べれば、実際には意味のない関連が見つかるかもしれません。pハッキングは、研究者の明確な不正だけでなく、発表しやすい結果を求める圧力、仮説を後から作る誘惑、ネガティブな結果が出版されにくい制度から生まれます。再現性危機の議論とも関係します。対策として、事前登録、データとコードの公開、効果量の重視、再現研究が進められています。この語を知ると、科学的という言葉にも方法の質が必要だと分かります。",
