    summary: "二つの事柄が一緒に変化することと、一方が他方の原因であることは別だという統計の基本。",
    explanation: "相関と因果は、統計を読むうえで最も重要な区別の一つです。相関とは、二つの事柄が一緒に増減する関係です。たとえばアイスクリームの売上と水難事故が同じ季節に増えるとしても、アイスクリームが事故を起こしているわけではありません。暑さという第三の要因が両方に関係している可能性があります。因果とは、一方が他方を引き起こす関係です。ニュースや広告では、ある食品を食べる人は健康だ、ある学習法を使う生徒は成績が良い、という相関から、すぐ原因のように語られることがあります。しかし、もともと健康意識が高い人がその食品を選んでいるだけかもしれません。因果を確かめるには、実験、自然実験、統計的調整、反事実の考え方が必要です。この区別を知ると、データに強く見える主張を鵜呑みにせず、何が原因で、何が単なる同時変化なのかを慎重に考えられます。",
    note: "相関は因果を証明しない。ただし因果推論の出発点にはなりうるため、相関を無意味とするのも誤り。",
