    explanation: "交絡因子は、調べたい原因と結果の両方に関係していて、見かけの関連を作ったり歪めたりする第三の要因です。たとえば、コーヒーを飲む人に病気が多いというデータがあったとしても、喫煙者がコーヒーを多く飲む傾向にあり、喫煙が病気の原因になっているなら、喫煙が交絡因子になります。コーヒーそのものの影響を知るには、喫煙の影響を分けて考える必要があります。交絡因子は医学、疫学、社会調査、教育政策、経済分析で非常に重要です。単純な比較では、所得、年齢、健康状態、地域、家庭環境、性格などが隠れた要因として働くことがあります。交絡を調整するには、ランダム化、層別化、回帰分析、マッチングなどの方法が使われます。この概念を知ると、データ上の関連を見た時に、別の要因が両方を動かしていないかを考える習慣がつきます。もっとも、測っていない交絡因子は調整できないため、研究設計が重要になります。",
    note: "交絡は因果推論の中心的な問題。単に第三の変数があるだけでなく、原因候補と結果の両方に関係する点が重要。",
