    explanation: "反事実は、実際には起きなかった別の可能性を考えることです。もしこの薬を飲まなかったらどうなっていたか、もし政策を実施しなかったら失業率はどうなったか、もし暗殺が起きなかったら歴史は変わったか。因果を考えるには、現実に起きた結果だけでなく、起きなかった場合との比較が必要です。医学や政策評価では、同じ人が同時に薬を飲む場合と飲まない場合を経験することはできません。そのため、ランダム化比較試験や統計的手法で反事実に近い比較対象を作ります。歴史でも、反事実は空想ではなく、ある出来事が本当に重要だったのかを考える道具になります。ただし、何でも自由に想像すると根拠のない物語になります。反事実を知ると、原因とは単に前に起きたものではなく、それがなければ結果がどう違ったかという比較の中で理解されることが分かります。",
